"""Readable Chinese report from accepted expanded230 aggregate metrics only; no NN."""
import argparse,csv,datetime,hashlib,json,pathlib,runpy,sys
METRICS=[('mae','MAE'),('rmse','RMSE'),('pearson','Pearson'),('spearman','Spearman'),('r2','R²'),('bias','Bias')]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def readcsv(p):
 with p.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def fmt(q,m):
 v=q.get(m+'_mean');s=q.get(m+'_sampleSD');return 'NA' if v in [None,''] else f'{float(v):.4f} ± {float(s):.4f}' if s not in [None,''] else f'{float(v):.4f} (SD=NA)'
def table(header,rr):return '\n'.join(['| '+' | '.join(header)+' |','| '+' | '.join(['---']*len(header))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rr])
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--utility',required=True);ap.add_argument('--comparison',type=pathlib.Path,required=True);ap.add_argument('--output',type=pathlib.Path,required=True);ap.add_argument('--training-stop-summary',type=pathlib.Path,required=True);a=ap.parse_args();u=runpy.run_path(a.utility);job,proc=u['guard']();proof=json.loads(a.comparison.read_text(encoding='utf-8-sig'));assert proof['status']=='passed' and proof['model_configurations']==23 and proof['model_seed_units']==230 and proof['splits']=={'train':531,'validation':570,'test':685,'external':0};base=a.comparison.parent
 for n,h in proof['metric_file_hashes'].items():assert sha(base/n)==h
 rr=readcsv(base/'COMBINED-230-ten-seed-summary.actual.csv');gm=readcsv(base/'COMBINED-GROUP-MACRO-23-ten-seed-summary.actual.csv');idx={(q['method'],q['stratum']):q for q in rr};gidx={q['method']:q for q in gm};assert len(rr)==230 and len(gm)==23
 full=['fullfine_hybrid','fullfine_mlm','fullfine_peptideclm2025'];families=['constant','ridge','random_forest','extra_trees','hist_gradient_boosting'];morgan=['morgan__'+f for f in families];primary=full+morgan;allmethods=full+[r+'__'+f for r in ['hybrid','mlm','morgan','peptideclm2025'] for f in families];names={'fullfine_hybrid':'CLM2 Hybrid 全参数','fullfine_mlm':'CLM2 MLM 全参数','fullfine_peptideclm2025':'PeptideCLM2025 全参数'}
 for m in allmethods:names.setdefault(m,m.replace('__',' / '))
 stopproof=json.loads(a.training_stop_summary.read_text(encoding='utf-8-sig'));assert stopproof['status']=='PASS' and len(stopproof['summary'])==3
 assert any(p.endswith('.json') and json.loads(pathlib.Path(p).read_text(encoding='utf-8-sig')).get('training60_proof_sha256')==stopproof['training_review_sha256'] for p in proof['source_pins'])
 for n,h in stopproof['metric_file_hashes'].items():assert sha(a.training_stop_summary.parent/n)==h
 stoprows=stopproof['summary'];assert {q['model'] for q in stoprows}=={'hybrid','mlm','2025'} and all(q['candidates']==20 for q in stoprows)
 sections=['# 扩充数据：化学模型与 Morgan 的公平比较','本报告比较同一批685条 TEST记录。训练531条、验证570条；三个化学编码器各跑10个随机种子、每个种子比较2个学习率，60个候选完整后只用验证集MAE选择30个模型。另有四种冻结表征各配五种头，共200组模型；合计23种配置、230个模型与种子组合。','表中数值为10种子的均值 ± 样本标准差；NA保留未定义值。标准肽572条、纯合成/D/骨架类45条、纯PTM41条、混合20条、其他非标准7条是五个互斥层。NC_all=113包含PTM，仅表示广义全部非标准化学记录；PTM_bearing=61包含混合类。','所有1786条记录的端点均为实验Kd点值转换的pKd。MAE、RMSE与Bias采用pKd的对数单位，相关系数和R²无单位；pKd误差1约对应Kd相差10倍。',
'## 同测试样本的总体结果',table(['配置']+[n for m,n in METRICS],[[names[m]]+[fmt(idx[(m,'all')],k) for k,n in METRICS] for m in primary]),'全部五种Morgan模型均展示；这些TEST结果的排序用于描述，不能作为重新选择主对照或调参的依据。MAE/RMSE越低越好，Pearson/Spearman/R²越高越好；Bias应结合正负方向及接近零的程度判断。','## 标准肽、非天然残基和PTM分别评价（MAE）',table(['配置','标准572','合成/D/骨架45','PTM41','混合20','其他非标准7'],[[names[m]]+[fmt(idx[(m,t)],'mae') for t in ['standard20_control','synthetic_D_backbone','PTM','synthetic_and_PTM','other_NC']] for m in primary]),'## 聚合化学层与标记敏感性（MAE）',table(['配置','全部非标准113（含PTM）','含PTM61','标记21','未标记664'],[[names[m]]+[fmt(idx[(m,t)],'mae') for t in ['NC_all','PTM_bearing','flagged','unflagged']] for m in primary]),'## 相同冻结表征普通头的对照','Extra Trees作为明确的同类普通头展示；它与其他四类头的全部结果一并保留。此表不把不同训练容量或表征维度解释为严格配平。',table(['配置','总体MAE','标准MAE','合成/D/骨架MAE','PTM MAE','混合MAE'],[[names[m]]+[fmt(idx[(m,t)],'mae') for t in ['all','standard20_control','synthetic_D_backbone','PTM','synthetic_and_PTM']] for m in full+['hybrid__extra_trees','mlm__extra_trees','peptideclm2025__extra_trees','morgan__extra_trees']]),'## 全部23种配置的六项总体指标',table(['配置']+[n for k,n in METRICS],[[names[m]]+[fmt(idx[(m,'all')],k) for k,n in METRICS] for m in allmethods]),'## 155个依赖组的宏平均','每组等权；相关性和R²只平均有定义的组，不能以零代替NA。逐种子的有效组数与总组数保留在组宏CSV。',table(['配置']+[n for k,n in METRICS],[[names[m]]+[fmt(gidx[m],k) for k,n in METRICS] for m in allmethods]),'## 解释范围','冻结表示的实际总维度为：Hybrid/MLM=512化学维+ESM320=832；PeptideCLM2025=768+320=1088；Morgan=2048个带手性、半径2的指纹bit+10个RDKit描述符+ESM320=2378，无AAC回退。全参数模型可学习参数分别为31,674,369与43,259,393，预训练化学主干和MLP均参与优化。', '全部五类普通头每族两个固定候选：常数均值/中位数；Ridge的alpha=0.1/10（StandardScaler仅在TRAIN拟合）；RF/ET均128棵树，候选为max_depth=10/min_samples_leaf=3或不限深度/leaf=2，max_features=sqrt；HistGB为100轮/15叶或150轮/31叶，learning_rate=0.05且关闭early_stopping。每族每seed只按VAL MAE择优，同分取candidate0；全微调则比较1e-5/3e-5两个学习率。', 'CLM2 Hybrid与MLM属于同一篇论文的两个权重版本；PeptideCLM2025来自第二篇论文，使用公开权重及明确的SPE输入和池化适配。这里是亲和力任务适配，不把三个模型写成三篇独立方法论文。','全参数模型同时优化化学编码器与MLP，冻结表征模型只训练普通头；模型容量、学习率搜索、特征维度832/1088及4/4/8GiB资源上限均有差异。相同的是实际数据、测试样本、种子集合、验证集选优与指标定义。预训练模型是否见过部分测试实体仍未知。','685条TEST保留上一版656条并增加29条，因此不是上一版的独立外部验证。当前独立外测金标准为0条；10个随机种子表示计算重复，不能当作10次独立生物实验。种子配对差值用于描述计算波动，不报告生物显著性。','## 可复核文件']
 at=sections.index('## 解释范围');sections[at:at]=['## 实际训练轮数与停止规则',table(['模型','候选数','epochs范围','epochs均值±样本SD','best epoch范围','patience5早停数','达到max30数'],[[q['model'],q['candidates'],str(q['epochs_min'])+'–'+str(q['epochs_max']),f"{q['epochs_mean']:.2f} ± {q['epochs_sampleSD']:.3f}",str(q['best_epoch_min'])+'–'+str(q['best_epoch_max']),q['patience5_before_budget'],q['max30_budget_complete']] for q in stoprows]),'停止规则根据实际epoch与stale游标和冻结max30/patience5推导。达到预算不等于收敛，patience早停也不建立收敛证明；未根据TEST修改预算或重新调参。训练统计收据SHA256：'+sha(a.training_stop_summary)+'。']
 for name in proof['metric_file_hashes']:sections.append(f'- [{name}]({(base/name).as_posix()}) — SHA256 {proof["metric_file_hashes"][name]}')
 sections+=['','审计收据SHA256：'+sha(a.comparison)+'。全部原预测、训练候选、验证集选择、日志与失败历史按项目索引保留。']
 assert not a.output.exists();a.output.write_text('\n\n'.join(sections)+'\n',encoding='utf-8');receipt={'schema':'expanded-v3.readable-report-provenance.v1','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'comparison_sha256':sha(a.comparison),'training_stop_summary_sha256':sha(a.training_stop_summary),'source_sha256':sha(pathlib.Path(__file__)),'report_sha256':sha(a.output),'metric_file_hashes':proof['metric_file_hashes'],'new_NN_fits_predictions':0,'process':proc};p=a.output.with_name('READABLE-REPORT-PROVENANCE.actual.json');assert not p.exists();p.write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps({'report':str(a.output),'sha256':sha(a.output),'provenance':str(p),'NN':0}))
if __name__=='__main__':main()
